/**
 * Builds the shared vector files (distribution plan D2): cases for the brain's pure
 * functions, with the answers the Node brain gives. The Node tests read them (and so
 * re-check every answer against brain/*.mjs on every run), and the Rust port must give
 * the same answers: cargo tests read the same files, and scripts/differential.mjs
 * compares the two implementations on generated cases beyond these.
 *
 *   node test/fixtures/build-vectors.mjs           rewrite the files from the cases below
 *   node test/fixtures/build-vectors.mjs --check   exit 1 if a file differs from what
 *                                                  the Node brain answers today
 *
 * The files are golden: after rewriting, read the diff and make sure every changed
 * answer is a change you meant before committing it.
 *
 *   redact-vectors.json      makeTextCleaner (redact, then truncate)
 *   normalise-vectors.json   normalise(): payload and headers in, HookEvent out
 *   config-vectors.json      validateConfig and withDefaults: the effective config, or the error
 *   diff-vectors.json        unifiedDiff and diffStats
 *   installer-vectors/       settings bytes in; the bytes after `hooks install`, its
 *                            preview, and the bytes after `hooks uninstall`
 *
 * The cases came out of the tests that read them (named in each group's `test`).
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateConfig } from '../../brain/config.mjs';
import { PALETTE_UPGRADED, withDefaults } from '../../brain/defaults.mjs';
import { diffStats, unifiedDiff } from '../../brain/diff.mjs';
import { applyPlan, planEdit } from '../../brain/hooks.mjs';
import { normalise } from '../../brain/normalise.mjs';
import { makeTextCleaner } from '../../brain/redact.mjs';

const DIR = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(DIR, '..', '..');
const TOKEN = 'testTokenNotReal_abcdefghijklmnop';
/** The port the installer vectors are made with (any port but the live 47417). */
export const INSTALLER_PORT = 47555;
const EXAMPLE_PATTERNS = JSON.parse(fs.readFileSync(path.join(REPO, 'config.example.json'), 'utf8')).bubble.redactPatterns;
const header = (what, test) => ({ comment: `${what} Generated by test/fixtures/build-vectors.mjs from the Node brain; read by ${test} and by the Rust port's tests. Don't edit by hand.`, node: process.version });

