/**
 * URL credentials: the userinfo runs to the LAST `@` before the host (milestone 3 fix; the
 * old rule stopped at the first `@` and left the rest of such a password readable).
 * [name, text, the fragment that must not survive, or null when nothing may be redacted].
 */
const URLS = [
  ['a password containing @ and :', 'curl https://u%40x:p@ss:w0rd@h.test/', 'ss:w0rd'],
  ['@ in the path is not userinfo', 'curl https://h.test/users/bob@example.com', null],
  ['@ in the query is not userinfo', 'curl "https://h.test/x?email=a:b@c.test"', null],
  ['an email in the path after real credentials', 'git clone https://bob:pw@h.test/bob@example.com/repo', 'pw@'],
  ['two URLs on one line', 'curl https://a:pw1@h1.test/x https://c:p@w2@h2.test/y', 'w2@'],
  ['two URLs separated by a comma', 'echo https://a:p@1@h1.test,https://b:q@2@h2.test', 'q@2'],
  ['a percent-encoded @ in the password', 'curl https://u:p%40ss@h.test/', 'p%40ss'],
  ['an unencoded @ in the user name', 'curl https://u@x:secret@h.test/', 'secret'],
  ['no path, empty user, @ in the password', 'export REDIS_URL=redis://:pa@ss@host:6379', 'pa@ss'],
  ['a port and a query without a path', 'curl https://u:p@ss@h.test:8443?x=1', 'p@ss'],
  ['a password longer than the old 500 limit', `curl https://u:${'p@'.repeat(300)}x@h.test/`, 'p@p@'],
  ['user name only: left alone (token shapes have their own rules)', 'git clone https://git@h.test/x', null],
  ['no scheme separator: scp syntax is not a URL', 'scp f.txt user@host:/tmp/', null],
  ['an empty password is left alone', 'curl https://u:@h.test/', null],
];

/**
 * Known gaps in the URL rule, pinned as they are today in both brains (BR-3K, milestone 3).
 * Not wanted behaviour: follow-ups in the plan's M3 status. [name, text, the gap].
 */
const URL_GAPS = [
  ['an unencoded / in the password ends the authority, so it leaks', 'curl https://u:pa/ss@h.test/', 'leak'],
  ['whitespace in the password ends the authority, so it leaks', 'curl https://u:pa ss@h.test/', 'leak'],
  ['an @ in a query right after host:port is read as userinfo, so the host is hidden', 'curl http://localhost:3000?email=me@x.io', 'over-redaction'],
];

/** tester-m2: redact first, then truncate, with the secret near the cut. */
const STRADDLE = [
  ...[30, 40, 45, 50, 52, 54, 56].map((pad) => [`sk- key after ${pad} characters`, `${'x'.repeat(pad)} sk-abcdefghijklmnopqrstuvwxyz0123456789 tail`]),
  ...[20, 30, 40, 47, 50].map((pad) => [`password= after ${pad} characters`, `${'y'.repeat(pad)} password=hunter2hunter2hunter2`]),
];

function redactVectors() {
  const vectors = [];
  const add = (group, test, name, text, maxChars, redactPatterns, extra = {}) => vectors.push({ group, test, name, text, maxChars, redactPatterns, expected: makeTextCleaner({ maxChars, redactPatterns })(text), ...extra });
  for (const [set, patterns] of [['built-in patterns only', []], ['config.example.json patterns', EXAMPLE_PATTERNS]]) {
    for (const [name, text, secret] of CORPUS) add(`credential corpus, ${set}`, 'tester-m2.test.mjs', name, text, 500, patterns, { mustNotContain: secret });
  }
  for (const [name, text, secret] of LEAKS) add('new secret shapes', 'tester-m2-recheck.test.mjs', name, text, 500, [], { mustNotContain: secret });
  for (const text of ORDINARY) add('ordinary commands', 'tester-m2-recheck.test.mjs', text, text, 500, [], { mustNotContain: '•••' });
  for (const [text, want] of READABLE) add('readable key', 'flock.test.mjs', text, text, 200, [], { mustEqual: want });
  for (const c of BIDI) add('bidi controls', 'flock.test.mjs', `U+${c.codePointAt(0).toString(16).toUpperCase()}`, `ls ${c}fdp.exe`, 60, [], { mustNotContain: c });
  for (const [name, text, maxChars] of UNICODE) add('unicode and controls', 'tester-m2.test.mjs', name, text, maxChars, []);
  for (const [name, text] of STRADDLE) add('redact before truncate', 'tester-m2.test.mjs', name, text, 60, []);
  for (const [name, text, secret] of URLS) add('URL credentials', 'tester-m2.test.mjs', name, text, 500, [], secret === null ? { mustEqual: text } : { mustNotContain: secret });
  for (const [name, text, gap] of URL_GAPS) add('URL credentials, known gaps', 'tester-m2.test.mjs', name, text, 500, [], { knownGap: gap });
  add('user patterns', 'flock.test.mjs', 'a (?i) user pattern', 'echo HUNTER2 and hunter3 but not hunterx', 60, ['(?i)hunter\\d']);
  return { ...header('Cases for makeTextCleaner({maxChars, redactPatterns})(text): `expected` is the Node answer; mustNotContain / mustEqual are what the test asserts.', 'the tests named in each vector'), examplePatterns: EXAMPLE_PATTERNS, vectors };
}

// ------------------------------------------------------------------ normalise

function normaliseVectors() {
  const SECRET = 'hunter2-do-not-keep';
  const vectors = [];
  const add = (group, test, name, payload, headers, receivedAt, clean) => {
    const ev = normalise(payload, headers, receivedAt, { clean: clean ? makeTextCleaner(clean) : null });
    vectors.push({ group, test, name, payload, headers, receivedAt, clean, expected: ev });
  };
  add('allowlist', 'brain.test.mjs', 'only allowlisted fields, no free text without a cleaner', {
    hook_event_name: 'PreToolUse',
    session_id: 'sess-1',
    cwd: '/Users/example/projects/demo',
    transcript_path: '/Users/example/.claude/projects/x.jsonl',
    prompt: `please use ${SECRET}`,
    tool_name: 'Bash',
    tool_use_id: 'toolu_01',
    tool_input: { command: `echo ${SECRET}`, description: SECRET },
    tool_output: SECRET,
    last_assistant_message: SECRET,
    some_future_field: SECRET,
    source: `free text ${SECRET}`,
  }, { 'x-bellwether-herdr-pane': 'w1:p2', 'x-bellwether-iterm-session': '', 'x-bellwether-token': 'tok', 'x-bellwether-term-program': 'iTerm.app' }, 123, null);
  for (const [name, value] of [['an identifier', 'Stop'], ['free text', `free text ${SECRET}`], ['an object', { x: 1 }]]) add('event names', 'brain.test.mjs', name, { hook_event_name: value }, {}, 1, null);
  add('messages', 'tester-m2.test.mjs', 'a Notification message is redacted', { hook_event_name: 'Notification', session_id: 's', notification_type: 'elicitation_dialog', message: 'Enter token=abc123def456ghi789' }, {}, 1, { maxChars: 80, redactPatterns: [] });
  add('messages', 'tester-m2.test.mjs', 'an Elicitation message is redacted', { hook_event_name: 'Elicitation', session_id: 's', mcp_server_name: 'srv', message: 'password: hunter2hunter2' }, {}, 1, { maxChars: 80, redactPatterns: [] });
  add('summaries', 'tester-m2.test.mjs', 'WebFetch shows the host only', { hook_event_name: 'PreToolUse', session_id: 's', tool_name: 'WebFetch', tool_input: { url: 'https://bob:pw123456@host.test/x?token=abc' } }, {}, 1, { maxChars: 60, redactPatterns: [] });
  add('summaries', 'tester-m2.test.mjs', 'Read shows the file name only', { hook_event_name: 'PreToolUse', session_id: 's', tool_name: 'Read', tool_input: { file_path: '/home/u/.aws/credentials' } }, {}, 1, { maxChars: 60, redactPatterns: [] });
  add('summaries', 'tester-m2.test.mjs', 'an MCP tool shows server:tool', { hook_event_name: 'PreToolUse', session_id: 's', tool_name: 'mcp__github__create_issue', tool_input: { title: SECRET } }, {}, 1, { maxChars: 60, redactPatterns: [] });
  add('agent types', 'tester-m6.test.mjs', 'a long agent_type is cut to 24 characters', { hook_event_name: 'PreToolUse', session_id: 's', agent_id: 'a', agent_type: 'abcdefghijklmnopqrstuvwxyz0123456789', tool_name: 'Read' }, {}, 1, { maxChars: 60, redactPatterns: [] });
  for (const t of ['<img src=x onerror=alert(1)>', 'a‮b', 'a\u0007b', 'a\nb', 'two words', '', 'x"y', "x'y", '`rm`', 'a;b', '%00', '​zw', 'a'.repeat(200), 'sk-abcdefghijklmnopqrstuvwxyz0123456789']) {
    add('agent types', 'tester-m6.test.mjs', `agent_type ${JSON.stringify(t.length > 40 ? `${t.slice(0, 12)}… (${t.length})` : t)}`, { hook_event_name: 'PreToolUse', session_id: 's', cwd: '/w/p', agent_id: 'a', agent_type: t, tool_name: 'Bash', tool_use_id: 't', tool_input: { command: 'ls' } }, { 'x-bellwether-herdr-pane': 'w1:p1', 'x-bellwether-herdr-socket': '/s' }, 1000, { maxChars: 60, redactPatterns: [] });
  }
  add('labels', 'flock.test.mjs', 'a folder name loses control, bidi and zero-width characters', { hook_event_name: 'Stop', session_id: 's', cwd: '/w/a‮b\u0007c​d' }, { 'x-bellwether-herdr-pane': 'w1:p1' }, 1, null);
  add('terminals', 'flock.test.mjs', 'every terminal header', { hook_event_name: 'Stop', session_id: 's' }, { 'x-bellwether-term-program': 'iTerm.app', 'x-bellwether-iterm-session': 'w0t1p0:00000000-AAAA-4BBB-8CCC-000000000001', 'x-bellwether-term-session': 'w0t1p0:x', 'x-bellwether-wt-session': 'wt-1', 'x-bellwether-tmux-pane': '%3', 'x-bellwether-herdr-pane': '-bad', 'x-bellwether-herdr-socket': 'relative.sock' }, 1, null);
  return { ...header('Cases for normalise(payload, headers, receivedAt, {clean}): `clean` is null or makeTextCleaner\'s options; `expected` is the HookEvent.', 'the tests named in each vector'), vectors };
}

// ------------------------------------------------------------------ config

function configVectors() {
  const example = JSON.parse(fs.readFileSync(path.join(REPO, 'config.example.json'), 'utf8'));
  const older = structuredClone(example);
  delete older.behaviour.thinkingTimeoutSec;
  const vectors = [];
  const add = (group, test, step, name, config) => {
    const v = { group, test, step, name, config };
    try {
      const out = step === 'validateConfig' ? validateConfig(structuredClone(config)) : withDefaults(structuredClone(config));
      v.ok = true;
      if (step === 'withDefaults') {
        v.effective = JSON.parse(JSON.stringify(out));
        v.paletteUpgraded = out[PALETTE_UPGRADED] === true;
      }
    } catch (e) {
      Object.assign(v, { ok: false, exitCode: e.exitCode, error: e.message });
    }
    vectors.push(v);
  };
  add('ports and hosts', 'brain.test.mjs', 'validateConfig', 'the example config', example);
  add('ports and hosts', 'brain.test.mjs', 'validateConfig', 'a top-level host', { port: 47417, host: '0.0.0.0' });
  add('ports and hosts', 'brain.test.mjs', 'validateConfig', 'a nested host', { port: 47417, brain: { host: '0.0.0.0' } });
  add('ports and hosts', 'brain.test.mjs', 'validateConfig', 'a HOST in capitals', { port: 47417, Host: 'x' });
  for (const [name, port] of [['no port', undefined], ['a string port', '47417'], ['port 80', 80], ['port 70000', 70000], ['port 1.5', 1.5], ['port 1024', 1024], ['port 65535', 65535]]) {
    add('ports and hosts', 'brain.test.mjs', 'validateConfig', name, port === undefined ? {} : { port });
  }
  add('ports and hosts', 'brain.test.mjs', 'validateConfig', 'an array', [47417]);
  for (const k of ['thinkingTimeoutSec', 'lambTimeoutMin', 'toolTimeoutMin']) {
    for (const v of [-1, '5', null]) add('behaviour', k === 'thinkingTimeoutSec' ? 'tester-m2.test.mjs' : 'tester-m2-recheck.test.mjs', 'withDefaults', `behaviour.${k} = ${JSON.stringify(v)}`, { port: 0, behaviour: { [k]: v } });
  }
  add('behaviour', 'tester-m2.test.mjs', 'withDefaults', 'thinkingTimeoutSec 0 is allowed', { port: 0, behaviour: { thinkingTimeoutSec: 0 } });
  add('behaviour', 'tester-m2.test.mjs', 'withDefaults', 'an older config without thinkingTimeoutSec gets the default', older);
  add('defaults', 'brain.test.mjs', 'withDefaults', 'the example config', example);
  add('defaults', 'brain.test.mjs', 'withDefaults', 'the old default palette is upgraded', { port: 0, pets: { palette: ['#FFFFFF', '#7fb3ff', '#ffb36b', '#9be37d', '#f28bd0', '#c9a2ff', '#ffe066', '#ff7b7b'] } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'an empty palette', { port: 0, pets: { palette: [] } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'tint "whole"', { port: 0, pets: { tint: 'whole' } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'tint "sparkly"', { port: 0, pets: { tint: 'sparkly' } });
  for (const n of [7, 8, 500, 501, 60.5]) add('defaults', 'brain.test.mjs', 'withDefaults', `bubble.maxChars ${n}`, { port: 0, bubble: { maxChars: n } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'bubble.detail "tool"', { port: 0, bubble: { detail: 'tool' } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'bubble.detail "none"', { port: 0, bubble: { detail: 'none' } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'a (?i) redact pattern', { port: 0, bubble: { redactPatterns: ['(?i)hunter\\d'] } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'a redact pattern that does not compile', { port: 0, bubble: { redactPatterns: ['(unclosed'] } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'an empty redact pattern', { port: 0, bubble: { redactPatterns: [''] } });
  add('defaults', 'brain.test.mjs', 'withDefaults', 'maxLambsShown 2.5', { port: 0, behaviour: { maxLambsShown: 2.5 } });
  return { ...header('Cases for config loading: `step` is validateConfig (port and host) or withDefaults (defaults merged, behaviour and bubble checked). `effective` is the merged config; an error carries exitCode and the message.', 'the tests named in each vector'), vectors };
}

// ------------------------------------------------------------------ installer and diff

const BASE = { theme: 'dark', n: 1.5, hooks: { Stop: [{ hooks: [{ type: 'command', command: 'k' }] }] } };
const FOREIGN = (port) => [
  { type: 'http', url: `http://127.0.0.1:${port}/hooks` },
  { type: 'http', url: `http://127.0.0.1:${port}/hook2` },
  { type: 'http', url: `http://127.0.0.1:${port}/hook?x=1` },
  { type: 'http', url: `http://127.0.0.1:${port}/hook/sub` },
];

/** [name, group, settings text]. `layout` is hooks.test.mjs's round-trip table. */
const INSTALLER = [
  ['tabs', 'layout', JSON.stringify(BASE, null, '\t') + '\n'],
  ['4 spaces, CRLF', 'layout', JSON.stringify(BASE, null, 4).replace(/\n/g, '\r\n') + '\r\n'],
  ['no trailing newline', 'layout', JSON.stringify(BASE, null, 2)],
  ['number literals 1.0, 1e2 and 2^70', 'layout', '{\n  "a": 1.0,\n  "b": 1e2,\n  "c": 1180591620717411303424,\n  "hooks": {}\n}\n'],
  ['an empty hooks object', 'layout', '{\n  "hooks": {}\n}\n'],
  ['no hooks key', 'layout', '{\n  "theme": "dark"\n}\n'],
  ['the settings sample', 'sample', fs.readFileSync(path.join(DIR, 'settings-sample.json'), 'utf8')],
  ['not in bellwether\'s layout', 'reformatted', '{ "theme": "dark", "list": [1, 2] }\n'],
  ['a __proto__ event key', 'proto', '{\n  "hooks": {\n    "__proto__": [\n      {\n        "hooks": [\n          {\n            "type": "command",\n            "command": "k"\n          }\n        ]\n      }\n    ]\n  }\n}\n'],
  ['foreign URLs near ours', 'foreign', JSON.stringify({ hooks: { Stop: [{ hooks: FOREIGN(INSTALLER_PORT) }], PreToolUse: [{ matcher: 'Bash', hooks: [FOREIGN(INSTALLER_PORT)[0]] }] } }, null, 2) + '\n'],
  ['exotic numbers, escapes and integer-like keys', 'exotic', '{\n  "b": 1,\n  "2": "two",\n  "1": "one",\n  "neg": -0,\n  "big": 12345678901234567890,\n  "e": 1E+2,\n  "s": "tab\\there \\u00e9 \\ud83d\\ude00 \\/ slash",\n  "hooks": {}\n}\n'],
];

const slug = (name) => name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

/** Runs install then uninstall the way the CLI does, in a temp dir. */
function installerCase(text) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bw-vectors-'));
  try {
    const file = path.join(dir, 'settings.json');
    const data = path.join(dir, 'data');
    fs.writeFileSync(file, text);
    const ins = planEdit(file, 'install', { port: INSTALLER_PORT, token: TOKEN, dataDir: data });
    const preview = unifiedDiff(ins.oldText, ins.newText, { oldName: 'settings.json (current)', newName: 'settings.json (after install)' });
    applyPlan(ins, path.join(dir, 'backups-install'), data);
    const installed = fs.readFileSync(file, 'utf8');
    const un = planEdit(file, 'uninstall', { port: INSTALLER_PORT, token: null, dataDir: data });
    const unPreview = unifiedDiff(un.oldText, un.newText, { oldName: 'settings.json (current)', newName: 'settings.json (after uninstall)' });
    applyPlan(un, path.join(dir, 'backups-uninstall'), data);
    return { installed, preview, unPreview, uninstalled: fs.readFileSync(file, 'utf8'), layoutKept: ins.layoutKept };
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

/** Returns { relative path: text } for installer-vectors/. */
function installerVectors() {
  const files = {};
  const cases = [];
  for (const [name, group, text] of INSTALLER) {
    const d = slug(name);
    const r = installerCase(text);
    files[`${d}/settings.json`] = text;
    files[`${d}/installed.json`] = r.installed;
    files[`${d}/install.diff`] = r.preview;
    files[`${d}/uninstall.diff`] = r.unPreview;
    files[`${d}/uninstalled.json`] = r.uninstalled;
    cases.push({ name, group, dir: d, layoutKept: r.layoutKept, roundTrip: r.uninstalled === text, text, installed: r.installed });
  }
  const listed = cases.map(({ text, installed, ...c }) => c);
  files['cases.json'] = JSON.stringify({ ...header(`Settings files through \`hooks install\` then \`hooks uninstall\` (port ${INSTALLER_PORT}, the test token). Each directory: settings.json in, installed.json and install.diff (the preview), uninstall.diff and uninstalled.json. roundTrip: uninstalled.json is byte-identical to settings.json.`, 'hooks.test.mjs'), port: INSTALLER_PORT, token: TOKEN, cases: listed }, null, 2) + '\n';
  return { files, cases };
}

function diffVectors(installer) {
  const vectors = [];
  const add = (group, name, oldText, newText, options = {}) => {
    const s = diffStats(oldText, newText);
    vectors.push({ group, name, old: oldText, new: newText, options, expected: unifiedDiff(oldText, newText, options), stats: { added: s.added, removed: s.removed } });
  };
  const lines = (n, f = (i) => `line ${i}`) => Array.from({ length: n }, (_, i) => f(i)).join('\n') + '\n';
  add('edges', 'identical', 'a\nb\n', 'a\nb\n');
  add('edges', 'empty to text', '', 'a\nb\n');
  add('edges', 'text to empty', 'a\nb\n', '');
  add('edges', 'CRLF against LF diff line for line', 'a\r\nb\r\n', 'a\nb\nc\n');
  add('edges', 'no trailing newline', 'a\nb', 'a\nc');
  add('edges', 'blank lines', '\n\n\n', '\n\nx\n\n');
  // A CR goes with the LF after it only (split(/\r?\n/)): a lone CR stays in its line.
  add('lone CR', 'a final lone CR is part of the last line', 'a\r', 'a');
  add('lone CR', 'a lone CR inside a line', 'a\rb\nc\n', 'a\rb\nd\n');
  add('lone CR', 'a line that is only a CR', 'a\n\r\nb\n\r', 'a\n\r\nb\n');
  add('lone CR', 'CR CR LF', 'x\r\r\ny\n', 'x\r\ny\n');
  add('hunks', 'two changes 6 lines apart share a hunk', lines(20), lines(20, (i) => (i === 5 || i === 11 ? `changed ${i}` : `line ${i}`)));
  add('hunks', 'two changes 7 lines apart get two hunks', lines(20), lines(20, (i) => (i === 5 || i === 12 ? `changed ${i}` : `line ${i}`)));
  add('hunks', 'a change on the first line', lines(10), lines(10, (i) => (i === 0 ? 'first' : `line ${i}`)));
  add('hunks', 'a change on the last line', lines(10), lines(10, (i) => (i === 9 ? 'last' : `line ${i}`)));
  add('hunks', 'context 1 and file names', lines(10), lines(10, (i) => (i === 4 ? 'mid' : `line ${i}`)), { oldName: 'x (current)', newName: 'x (after)', context: 1 });
  add('hunks', 'repeated lines (LCS ties)', 'a\na\nb\na\n', 'a\nb\na\na\n');
  for (const c of installer.cases) add('installer previews', c.name, c.text, c.installed, { oldName: 'settings.json (current)', newName: 'settings.json (after install)' });
  return { ...header('Cases for unifiedDiff(old, new, options) and diffStats(old, new): `expected` is the diff text, `stats` the added and removed line counts.', 'hooks.test.mjs'), vectors };
}

// ------------------------------------------------------------------ write or check

function build() {
  const installer = installerVectors();
  const out = {
    'redact-vectors.json': JSON.stringify(redactVectors(), null, 2) + '\n',
    'normalise-vectors.json': JSON.stringify(normaliseVectors(), null, 2) + '\n',
    'config-vectors.json': JSON.stringify(configVectors(), null, 2) + '\n',
    'diff-vectors.json': JSON.stringify(diffVectors(installer), null, 2) + '\n',
  };
  for (const [rel, text] of Object.entries(installer.files)) out[path.join('installer-vectors', rel)] = text;
  return out;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const out = build();
  const stale = [];
  for (const [rel, text] of Object.entries(out)) {
    const file = path.join(DIR, rel);
    // The Node version only labels the files; a different Node is not a difference.
    const comparable = (t) => t.replace(/"node": "v[^"]*"/, '"node": ""');
    const now = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (now !== null && comparable(now) === comparable(text)) continue;
    if (check) stale.push(rel);
    else {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, text);
      console.log(`wrote test/fixtures/${rel}`);
    }
  }
  if (check) {
    if (stale.length) {
      console.error(`build-vectors: these differ from what the Node brain answers now:\n  ${stale.join('\n  ')}\nRun \`node test/fixtures/build-vectors.mjs\`, read the diff, and commit it if every change is meant.`);
      process.exit(1);
    }
    console.log(`build-vectors: all ${Object.keys(out).length} vector files match the Node brain`);
  }
}
